from __future__ import annotations

# Importierte Module:
# argparse = Kommandozeilenargumente, copy = Objekte kopieren, json = Text als String-Literal,
# re = reguläre Ausdrücke, uuid = eindeutige IDs, ET = XML lesen/schreiben,
# dataclass/field = Datenklassen, datetime = Datum/Zeit, count = Zähler,
