DEFAULT_LIB["TYP_IPO"] = _block_from_pou_xml("<pou xmlns=\"http://www.plcopen.org/xml/tc6_0200\" xmlns:html=\"http://www.w3.org/1999/xhtml\" name=\"TYP_IPO\" pouType=\"functionBlock\">\n        <interface>\n          <inputVars>\n            <variable name=\"Start\">\n              <type>\n                <BOOL />\n              </type>\n            </variable>\n            <variable name=\"qZiel\">\n              <type>\n                <REAL />\n              </type>\n            </variable>\n            <variable name=\"qStart\">\n              <type>\n                <REAL />\n              </type>\n            </variable>\n            <variable name=\"v\">\n              <type>\n                <REAL />\n              </type>\n            </variable>\n            <variable name=\"a\">\n              <type>\n                <REAL />\n              </type>\n            </variable>\n          </inputVars>\n          <outputVars>\n            <variable name=\"qSoll\">\n              <type>\n                <REAL />\n              </type>\n            </variable>\n          </outputVars>\n          <localVars>\n            <variable name=\"sp\">\n              <type>\n                <REAL />\n              </type>\n            </variable>\n            <variable name=\"t\">\n              <type>\n                <REAL />\n              </type>\n            </variable>\n            <variable name=\"t1\">\n              <type>\n                <REAL />\n              </type>\n            </variable>\n            <variable name=\"t2\">\n              <type>\n                <REAL />\n              </type>\n            </variable>\n            <variable name=\"t3\">\n              <type>\n                <REAL />\n              </type>\n            </variable>\n            <variable name=\"uhr\">\n              <type>\n                <derived name=\"TON\" />\n              </type>\n            </variable>\n            <variable name=\"Dist\">\n              <type>\n                <REAL />\n              </type>\n            </variable>\n          </localVars>\n        </interface>\n        <body>\n          <ST>\n            <html:xhtml>Dist:=ABS(qZiel-qStart);\nv:=LIMIT(0.00001, v, SQRT(Dist*a));\t\t(* zeitoptimale Bahn *)\nt2:= Dist/v;\nt1:= v/MAX(a,0.000000001);\nt3:= t1+t2;\nuhr(IN:=Start,pt:=REAL_TO_TIME(t3));\nt:=TIME_TO_REAL(uhr.ET);\nIF t &lt; t1 THEN\n\tsp:= 0.5*a*t*t;\nELSIF t &gt;= t1 AND t&lt;t2 THEN\n\tsp:= 0.5*a*t1*t1+ v*(t-t1);\nELSIF t &gt;= t2 AND t&lt;t3 THEN\n\tsp:= 0.5*a*t1*t1+ v*(t2-t1)+ v*(t-t2) - 0.5*a*(t-t2)*(t-t2);\nELSIF t&gt;=t3 THEN\n\tsp:= Dist;\nEND_IF\nIF qZiel&gt;=qStart THEN\n\tqSoll:=sp+qStart;\nEND_IF\nIF qZiel&lt;qStart THEN\n\tqSoll:=-sp+qStart;\nEND_IF\n</html:xhtml>\n          </ST>\n        </body>\n        <addData>\n          <data name=\"http://www.3s-software.com/plcopenxml/objectid\" handleUnknown=\"discard\">\n            <ObjectId>a15fdd97-598f-422b-80bd-25ebbf204fee</ObjectId>\n          </data>\n        </addData>\n      </pou>\n      ")
